CREATE TABLE public.party_event (id int PRIMARY KEY DEFAULT 1 CHECK(id=1), name text NOT NULL DEFAULT 'Festa na Chácara', party_date date, guests int CHECK(guests>0));
GRANT SELECT ON public.party_event TO anon, authenticated; GRANT ALL ON public.party_event TO service_role;
ALTER TABLE public.party_event ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_read ON public.party_event FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.party_categories(id int PRIMARY KEY, name text NOT NULL UNIQUE, icon text NOT NULL);
GRANT SELECT ON public.party_categories TO anon,authenticated; GRANT ALL ON public.party_categories TO service_role;
ALTER TABLE public.party_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY categories_read ON public.party_categories FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.party_participants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(trim(name)) BETWEEN 2 AND 60), token_hash text NOT NULL UNIQUE, created_at timestamptz DEFAULT now());
GRANT ALL ON public.party_participants TO service_role;
ALTER TABLE public.party_participants ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.party_products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100), category_id int NOT NULL REFERENCES public.party_categories(id), quantity numeric CHECK(quantity>0), unit text NOT NULL DEFAULT 'un.', note text, received boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX product_name_category ON public.party_products(lower(trim(name)),category_id);
GRANT SELECT ON public.party_products TO anon,authenticated; GRANT ALL ON public.party_products TO service_role;
ALTER TABLE public.party_products ENABLE ROW LEVEL SECURITY;
CREATE POLICY products_read ON public.party_products FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.party_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.party_products(id) ON DELETE CASCADE, participant_id uuid NOT NULL REFERENCES public.party_participants(id), participant_name text NOT NULL, quantity numeric NOT NULL CHECK(quantity>0), source text NOT NULL CHECK(source IN ('home','buy')), created_at timestamptz DEFAULT now());
GRANT SELECT ON public.party_reservations TO anon,authenticated; GRANT ALL ON public.party_reservations TO service_role;
ALTER TABLE public.party_reservations ENABLE ROW LEVEL SECURITY;
CREATE POLICY reservations_read ON public.party_reservations FOR SELECT TO anon,authenticated USING(true);
CREATE FUNCTION public.validate_party_reservation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE needed numeric; taken numeric; is_received boolean; BEGIN SELECT quantity,received INTO needed,is_received FROM public.party_products WHERE id=NEW.product_id FOR UPDATE; IF is_received THEN RAISE EXCEPTION 'Este item já foi recebido.'; END IF; SELECT coalesce(sum(quantity),0) INTO taken FROM public.party_reservations WHERE product_id=NEW.product_id AND id<>NEW.id; IF needed IS NOT NULL AND taken+NEW.quantity>needed THEN RAISE EXCEPTION 'A quantidade ultrapassa o que ainda falta.'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER reservation_limit BEFORE INSERT OR UPDATE ON public.party_reservations FOR EACH ROW EXECUTE FUNCTION public.validate_party_reservation();
CREATE FUNCTION public.validate_party_product() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.quantity IS NOT NULL AND NEW.quantity<(SELECT coalesce(sum(quantity),0) FROM public.party_reservations WHERE product_id=NEW.id) THEN RAISE EXCEPTION 'Cancele as reservas excedentes antes de reduzir a quantidade.'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER product_limit BEFORE UPDATE ON public.party_products FOR EACH ROW EXECUTE FUNCTION public.validate_party_product();
ALTER PUBLICATION supabase_realtime ADD TABLE public.party_event,public.party_products,public.party_reservations;